from agent import *from models.products import *import simplejsonimport reXCAT = ['Angebote', 'Online Kurse']def remove_emoji(string):    emoji_pattern = re.compile("["                               u"\U0001F600-\U0001F64F"  # emoticons                               u"\U0001F300-\U0001F5FF"  # symbols & pictographs                               u"\U0001F680-\U0001F6FF"  # transport & map symbols                               u"\U0001F1E0-\U0001F1FF"  # flags (iOS)                               u"\U00002500-\U00002BEF"  # chinese char                               u"\U00002702-\U000027B0"                               u"\U00002702-\U000027B0"                               u"\U000024C2-\U0001F251"                               u"\U0001f926-\U0001f937"                               u"\U00010000-\U0010ffff"                               u"\u2640-\u2642"                               u"\u2600-\u2B55"                               u"\u200d"                               u"\u23cf"                               u"\u23e9"                               u"\u231a"                               u"\ufe0f"  # dingbats                               u"\u3030"                               "]+", flags=re.UNICODE)    return emoji_pattern.sub(r'', string)def run(context: dict[str, str], session: Session):    session.sessionbreakers = [SessionBreak(max_requests=6000)]    session.queue(Request('https://www.arktis.de/', use="curl", force_charset='utf-8', max_age=0), process_frontpage, dict())def process_frontpage(data: Response, context: dict[str, str], session: Session):    cats1 = data.xpath('//ul[contains(@class, "list-menu--inline")]/li ')    for cat1 in cats1:        name1 = cat1.xpath('span/text()').string()        if name1 not in XCAT:            cats2 = cat1.xpath('ul/li')            for cat2 in cats2:                name2 = cat2.xpath('a/text()').string() or cat2.xpath('text()').string(multiple=True)                if name2:                    name2 = name2.strip()                url = cat2.xpath('a/@href').string()                cats3 = cat2.xpath('ul/li/a')                if not cats3:                    session.queue(Request(url, use="curl", force_charset='utf-8', max_age=0), process_prodlist, dict(cat=name1+'|'+name2))                for cat3 in cats3:                    name3 = cat3.xpath('text()').string()                    url = cat3.xpath('@href').string()                    session.queue(Request(url, use="curl", force_charset='utf-8', max_age=0), process_prodlist, dict(cat=name1+'|'+name2+'|'+name3))def process_prodlist(data: Response, context: dict[str, str], session: Session):    prods = data.xpath('//h3[contains(@class, "card-information")]/a')    for prod in prods:        name = prod.xpath('text()').string()        url = prod.xpath('@href').string().split('?')[0]        session.queue(Request(url, use="curl", force_charset='utf-8', max_age=0), process_product, dict(context, name=name, url=url))    next_url = data.xpath('//link[@rel="next"]/@href').string()    if next_url:        session.queue(Request(next_url, use="curl", force_charset='utf-8', max_age=0), process_prodlist, context)def process_product(data: Response, context: dict[str, str], session: Session):    product = Product()    product.name = context['name']    product.category = context['cat']    product.url = context['url']    product.ssid = data.xpath('//input[@name="product-id"]/@value').string()    sku = data.xpath('//div[@id="custom-sku"]/text()').string()    if sku:        product.sku = sku.split(': ')[-1].strip()    ean = data.xpath('''//script[contains(., '"barcode":"')]/text()''').string()    if ean:        ean = ean.split('"barcode":"')[-1].split('"', 1)[0]        product.properties.append(ProductProperty(type='id.ean', value=ean))    prod_json = data.xpath('''//script[contains(., '"@type": "Product"')]/text()''').string()    if prod_json:        prod_json = simplejson.loads(prod_json)        product.manufacturer = prod_json.get('brand', {}).get('name')    url_code = data.xpath('//div[@class="ruk_rating_snippet"]/@data-sku').string()    if url_code:        url = 'https://api.reviews.io/timeline/data?type=product_review&store=arktis.de&sku={}&per_page=10000'.format(url_code)        session.do(Request(url, use="curl", force_charset='utf-8', max_age=0), process_reviews, dict(product=product))    if product.reviews:        session.emit(product)def process_reviews(data: Response, context: dict[str, str], session: Session):    product = context["product"]    revs_json = simplejson.loads(data.content)    revs = revs_json.get('timeline', [])    for rev in revs:        rev = rev.get('_source', {})        review = Review()        review.url = product.url        review.type = "user"        review.ssid = rev['_id'].split('-')[-1]        date = rev.get('date_created')        if date:            review.date = date.split()[0]        author_name = rev.get('author')        author_ssid = rev.get('user_id')        if author_name and author_ssid:            review.authors.append(Person(name=author_name, ssid=str(author_ssid)))        elif author_name:            review.authors.append(Person(name=author_name, ssid=author_name))        is_verified = rev.get('order_id')        if is_verified:            review.add_property(type='is_verified_buyer', value=True)        hlp_yes = rev.get('helpful')        if hlp_yes:            review.add_property(type='helpful_votes', value=int(hlp_yes))        is_recommended = rev.get('would_recommend_product')        if is_recommended:            review.properties.append(ReviewProperty(value=True, type='is_recommended'))        grade_overall = rev.get('rating')        if grade_overall:            review.grades.append(Grade(type="overall", value=float(grade_overall), best=5.0))        excerpt = rev.get('comments')        if excerpt:            excerpt = remove_emoji(excerpt).replace('\r', '').replace('\n', '').strip()            if excerpt:                review.add_property(type="excerpt", value=excerpt)                product.reviews.append(review)    # All revs